/* ============================================================
   Araucária: tudo sobre esta planta fica nesta pasta.
   kind: 'tree' · árvore do ecossistema
   grow(ctx, x, z) cria o modelo na posição (x, z) e devolve { top } (altura para pouso/bugios)

   Modelo 3D realista: "Maple tree"
   por atrodler (https://sketchfab.com/atrodler), licença CC-BY-4.0
   https://sketchfab.com/3d-models/maple-tree-4b27adcf92f644bdabf8ecc6c5bef399
   (só a árvore: tronco e folhas; o mato do chão do modelo original foi removido)
   ============================================================ */

/* --- Dados do modelo 3D embutidos (NÃO EDITAR; sem arquivos externos, funciona abrindo direto o index.html) --- */
const ARAUCARIA_MESH = {"bark":{"n":13353,"pos":"","nrm":"","uv":"","idx":""},"leaf":{"n":12976,"pos":"","nrm":"","uv":"","idx":""},"barkTex":"data:image/jpeg;base64,","leafTex":"data:image/png;base64,","topY":1.0,"radius":0.38898898816799404};

registerPlant('araucaria', {
  kind: 'tree',
  weight: 1,   /* chance relativa de aparecer */

  grow(ctx, x, z) {
    const { scene, rnd, shade } = ctx;
    const sh = araucariaShared();
    const H = rnd(11, 15);                                   /* altura total da árvore */
    const t = new THREE.Group();

    const bark = new THREE.Mesh(sh.bark, sh.barkMat); bark.scale.setScalar(H); bark.castShadow = true; bark.receiveShadow = true; t.add(bark);
    const leaves = new THREE.Mesh(sh.leaf, sh.leafMats[Math.floor(rnd(0, sh.leafMats.length)) % sh.leafMats.length]);
    leaves.scale.setScalar(H); leaves.castShadow = true; leaves.receiveShadow = true;
    leaves.customDepthMaterial = sh.leafDepth;               /* sombra recortada no formato das folhas */
    t.add(leaves);

    t.rotation.y = rnd(0, Math.PI * 2);
    t.position.set(x, 0, z);
    if (shade) shade(t);
    scene.add(t);
    return { top: H * ARAUCARIA_MESH.topY + .3 };
  }
});

/* Geometrias, texturas e materiais compartilhados por todas as árvores (criados uma única vez). */
let _araucariaShared = null;
function araucariaShared() {
  if (_araucariaShared) return _araucariaShared;
  const D = ARAUCARIA_MESH;
  const bytes = b64 => { const s = atob(b64), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; };
  const make = P => {
    const n = P.n, i16 = new Int16Array(bytes(P.pos).buffer), i8 = new Int8Array(bytes(P.nrm).buffer),
          uv16 = new Int16Array(bytes(P.uv).buffer), idx = new Uint16Array(bytes(P.idx).buffer);
    const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3), uv = new Float32Array(n * 2);
    for (let i = 0; i < n * 3; i++) { pos[i] = i16[i] / 32000; nrm[i] = i8[i] / 127; }
    for (let i = 0; i < n * 2; i++) uv[i] = uv16[i] / 4096;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    geo.computeBoundingSphere();
    return geo;
  };
  const tex = url => {
    const t = new THREE.TextureLoader().load(url);
    t.encoding = THREE.sRGBEncoding; t.anisotropy = 4; t.wrapS = t.wrapT = THREE.RepeatWrapping;   /* UVs repetem / são negativos */
    return t;
  };
  const barkTex = tex(D.barkTex), leafTex = tex(D.leafTex);
  const barkMat = new THREE.MeshStandardMaterial({ map: barkTex, roughness: 1, metalness: 0 });
  /* 3 variações de verde para as árvores não ficarem iguais */
  const leafMats = [[1, 1, 1], [1.08, 1.02, .8], [.88, 1.05, .95]].map(c => {
    const m = new THREE.MeshStandardMaterial({ map: leafTex, roughness: .9, metalness: 0, side: THREE.DoubleSide, alphaTest: .5 });
    m.color.setRGB(c[0], c[1], c[2]); return m;
  });
  const leafDepth = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking, map: leafTex, alphaTest: .5 });
  return (_araucariaShared = { bark: make(D.bark), leaf: make(D.leaf), barkMat, leafMats, leafDepth });
}
